interface Goal {
  id: string;
  metric: () => Promise<number>;
  target: number;
}

class GoalMonitor {
  private goals: Goal[];
  async tick(state: WorldState) {
    for (const g of this.goals) {
      const v = await g.metric();
      if (v >= g.target) state.completed.push(g.id);
      else if (v < state.last.get(g.id)! * 0.5) state.replan.add(g.id);
      state.last.set(g.id, v);
    }
  }
}
